index chatlog_archive: CREATE UNIQUE INDEX chatlog_archive on chatlog(room, archive)
index chatlog_room: CREATE INDEX chatlog_room on chatlog(room, id)
index offline_account: CREATE INDEX offline_account on offline(account, id)
table affiliations: CREATE TABLE affiliations (room text not null, address text not null, affiliation text not null, nick text not null default '', primary key (room, address))
table chatlog: CREATE TABLE chatlog (id integer primary key autoincrement, room text not null, archive text not null, nick text not null, sender text not null default '', stanza text not null, created integer not null)
table items: CREATE TABLE items (account text not null, node text not null, item text not null, payload text not null, updated integer not null, primary key (account, node, item))
table joined: CREATE TABLE joined (account text not null, address text not null, room text not null, nick text not null, name text not null default '', seen integer not null default 0, created integer not null, primary key (account, room))
table nodes: CREATE TABLE nodes (account text not null, node text not null, access text not null default 'presence', maximum integer not null default 1, created integer not null, primary key (account, node))
table offline: CREATE TABLE offline (id integer primary key autoincrement, account text not null, stanza text not null, created integer not null)
table pushes: CREATE TABLE pushes (account text not null, service text not null, node text not null, options text not null default '', created integer not null, primary key (account, service, node))
table rooms: CREATE TABLE rooms (address text not null primary key, name text not null default '', description text not null default '', subject text not null default '', subjector text not null default '', persistent integer not null default 0, members integer not null default 0, public integer not null default 0, moderated integer not null default 0, open integer not null default 0, invite integer not null default 0, whois text not null default 'moderators', history integer not null default 20, locked integer not null default 0, created integer not null, updated integer not null)
table roster: CREATE TABLE roster (account text not null, address text not null, name text not null default '', subscription text not null default 'none', ask integer not null default 0, pending integer not null default 0, listed integer not null default 0, created integer not null, updated integer not null, primary key (account, address))
table secrets: CREATE TABLE secrets (name text not null primary key, value text not null)
table uploads: CREATE TABLE uploads (id text not null primary key, user text not null, account text not null default '', domain text not null, name text not null, type text not null, size integer not null, token text not null default '', created integer not null, stored integer not null default 0)
